const email = $json;

const cuerpo = email.text || "";

function extraer(etiqueta, siguienteEtiqueta) {
  const inicio = cuerpo.toUpperCase().indexOf(etiqueta.toUpperCase());

  if (inicio === -1) {
    return "";
  }

  const inicioValor = inicio + etiqueta.length;

  let fin = cuerpo.length;

  if (siguienteEtiqueta) {
    const posicionSiguiente = cuerpo.toUpperCase().indexOf(
      siguienteEtiqueta.toUpperCase(),
      inicioValor
    );

    if (posicionSiguiente !== -1) {
      fin = posicionSiguiente;
    }
  }

  return cuerpo.substring(inicioValor, fin).trim();
}

let remitente = "";

if (
  email.from &&
  email.from.value &&
  email.from.value[0] &&
  email.from.value[0].address
) {
  remitente = email.from.value[0].address;
}

return [
  {
    json: {
      // Datos del correo
      asunto: email.subject || "",
      remitente: remitente,
      fecha_recepcion: email.date || new Date().toISOString(),

      gmail_message_id: email.id || "",
      gmail_thread_id: email.threadId || "",

      // Datos de la consulta
      consulta_id: extraer("ID CONSULTA:", "FECHA:"),
      fecha: extraer("FECHA:", "DATOS DEL CONSULTANTE"),
      nombre: extraer("NOMBRE Y APELLIDO:", "EMAIL:"),
      email: extraer("EMAIL:", "TELÉFONO:"),
      telefono: extraer("TELÉFONO:", "CONSULTA"),
      area: extraer("ÁREA:", "ASUNTO:"),
      asunto_consulta: extraer("ASUNTO:", "FECHA DEL HECHO:"),
      fecha_hecho: extraer("FECHA DEL HECHO:", "URGENCIA:"),
      urgencia: extraer("URGENCIA:", "DOCUMENTACIÓN DISPONIBLE:"),
      documentacion_disponible: extraer(
        "DOCUMENTACIÓN DISPONIBLE:",
        "DESCRIPCIÓN:"
      ),
      descripcion: extraer(
        "DESCRIPCIÓN:",
        "PREFERENCIA DE CONTACTO:"
      ),
      preferencia_contacto: extraer(
        "PREFERENCIA DE CONTACTO:",
        "CONSENTIMIENTO:"
      ),
      consentimiento: extraer("CONSENTIMIENTO:", null),

      // Cuerpo original
      cuerpo_original: cuerpo
    }
  }
];

const faltantes = [];

if (!$json.consulta_id || !$json.consulta_id.trim()) {
  faltantes.push("ID de consulta");
}

if (!$json.nombre || !$json.nombre.trim()) {
  faltantes.push("Nombre y apellido");
}

if (!$json.email || !$json.email.trim()) {
  faltantes.push("Email");
}

if (!$json.area || !$json.area.trim()) {
  faltantes.push("Área de la consulta");
}

if (!$json.descripcion || !$json.descripcion.trim()) {
  faltantes.push("Descripción de la consulta");
}

if (!$json.consentimiento || $json.consentimiento.trim().toLowerCase() !== "sí") {
  faltantes.push("Consentimiento");
}

return [
  {
    json: {
      ...$json,

      datos_faltantes: faltantes,
      cantidad_datos_faltantes: faltantes.length,

      datos_faltantes_texto:
        faltantes.length > 0
          ? faltantes.map(dato => `- ${dato}`).join("\n")
          : ""
    }
  }
];
